","schema_name":"trdandb"},{"error_wrapper":false,"guard_relations":["tr_dandb_wb_la.dandb_wb_la_business_2024"],"relation_name":"dandb_wb_la_business_2024","relation_oid":"3750204751","schema_name":"trdandb"},{"error_wrapper":false,"guard_relations":["tr_dandb_wb_la.dandb_wb_la_delete_2012"],"relation_name":"dandb_wb_la_delete_2012","relation_oid":"3750204756","schema_name":"trdandb"},{"error_wrapper":false,"guard_relations":["tr_dandb_wb_la.dandb_wb_la_delete_2013"],"relation_name":"dandb_wb_la_delete_2013","relation_oid":"3750204760","schema_name":"trdandb"},{"error_wrapper":false,"guard_relations":["tr_dandb_wb_la.dandb_wb_la_delete_2014"],"relation_name":"dandb_wb_la_delete_2014","relation_oid":"3750204764","schema_name":"trdandb"},{"error_wrapper":false,"guard_relations":["tr_dandb_wb_la.dandb_wb_la_delete_2015"],"relation_name":"dandb_wb_la_delete_2015","relation_oid":"3750204768","schema_name":"trdandb"},{"error_wrapper":false,"guard_relations":["tr_dandb_wb_la.dandb_wb_la_delete_2016"],"relation_name":"dandb_wb_la_delete_2016","relation_oid":"3750204772","schema_name":"trdandb"},{"error_wrapper":false,"guard_relations":["tr_dandb_wb_la.dandb_wb_la_delete_2017"],"relation_name":"dandb_wb_la_delete_2017","relation_oid":"3750204776","schema_name":"trdandb"},{"error_wrapper":false,"guard_relations":["tr_dandb_wb_la.dandb_wb_la_delete_2018"],"relation_name":"dandb_wb_la_delete_2018","relation_oid":"3750204780","schema_name":"trdandb"},{"error_wrapper":false,"guard_relations":["tr_dandb_wb_la.dandb_wb_la_delete_2019"],"relation_name":"dandb_wb_la_delete_2019","relation_oid":"3750204784","schema_name":"trdandb"},{"error_wrapper":false,"guard_relations":["tr_dandb_wb_la.dandb_wb_la_delete_2020"],"relation_name":"dandb_wb_la_delete_2020","relation_oid":"3750204788","schema_name":"trdandb"}]'::jsonb)
    LOOP
        checked := clock_timestamp();
        result := jsonb_build_object(
            'relation_oid', item->'relation_oid',
            'schema_name', item->>'schema_name',
            'relation_name', item->>'relation_name',
            'checked_at', checked,
            'method', 'select_limit0_and_observed_alias_guards',
            'guard_relations', item->'guard_relations',
            'status', 'planning_accepted',
            'zero_row_status', 'not_run',
            'guard_status', 'not_present',
            'runtime_wrapper_status', 'not_run',
            'sqlstate', NULL, 'error', NULL);
        BEGIN
            EXECUTE format('SELECT * FROM %I.%I LIMIT 0',
                           item->>'schema_name', item->>'relation_name');
            result := result || jsonb_build_object('zero_row_status', 'accepted');
            IF jsonb_array_length(item->'guard_relations') > 0 THEN
                result := result || jsonb_build_object('guard_status', 'accepted');
            END IF;
            FOR guard IN SELECT jsonb_array_elements_text(item->'guard_relations')
            LOOP
                BEGIN
                    SELECT pg_catalog.has_table_privilege(guard, 'SELECT') INTO permitted;
                    IF NOT permitted THEN
                        result := result || jsonb_build_object(
                            'status', 'guard_denied', 'guard_status', 'false',
                            'error', 'Observed alias privilege guard returned false');
                    END IF;
                EXCEPTION WHEN OTHERS THEN
                    GET STACKED DIAGNOSTICS message = MESSAGE_TEXT, code = RETURNED_SQLSTATE;
                    result := result || jsonb_build_object(
                        'status', 'guard_denied', 'guard_status', 'error',
                        'sqlstate', code, 'error', message);
                END;
            END LOOP;
            IF (item->>'error_wrapper')::boolean THEN
                BEGIN
                    EXECUTE format('SELECT * FROM %I.%I LIMIT 1',
                                   item->>'schema_name', item->>'relation_name');
                    result := result || jsonb_build_object(
                        'method', 'select_limit0_and_error_wrapper_limit1',
                        'runtime_wrapper_status', 'accepted');
                EXCEPTION WHEN OTHERS THEN
                    GET STACKED DIAGNOSTICS message = MESSAGE_TEXT, code = RETURNED_SQLSTATE;
                    result := result || jsonb_build_object(
                        'method', 'select_limit0_and_error_wrapper_limit1',
                        'status', 'runtime_error', 'runtime_wrapper_status', 'error',
                        'sqlstate', code, 'error', message);
                END;
            END IF;
        EXCEPTION WHEN OTHERS THEN
            GET STACKED DIAGNOSTICS message = MESSAGE_TEXT, code = RETURNED_SQLSTATE;
            result := result || jsonb_build_object(
                'status', CASE WHEN code = '42501' THEN 'permission_denied' ELSE 'planning_error' END,
                'zero_row_status', 'error', 'sqlstate', code, 'error', message);
        END;
        result := result || jsonb_build_object(
            'duration_ms', round(extract(epoch from (clock_timestamp()-checked))*1000, 3));
        RAISE NOTICE 'CATALOG_PROBE %', result::text;
    END LOOP;
END
